export const BYTE_VOCAB_SIZE = 257;
export const EOS_TOKEN_ID = 256;

export class ByteTokenizer {
  public encode(text: string, appendEos = true): number[] {
    const bytes = Array.from(new TextEncoder().encode(text), (byte) => byte);
    if (appendEos) bytes.push(EOS_TOKEN_ID);
    return bytes;
  }

  /**
   * Decode only a valid UTF-8 prefix. Generated byte-level models often stop in
   * the middle of a multibyte character or emit invalid byte sequences; silently
   * rendering U+FFFD makes those failures look like visible text corruption.
   * Keep the longest valid prefix and discard the invalid suffix instead.
   */
  public decode(tokens: readonly number[]): string {
    const bytes: number[] = [];
    for (const token of tokens) {
      if (!Number.isInteger(token) || token < 0 || token >= BYTE_VOCAB_SIZE) {
        throw new RangeError(`Invalid token ID: ${token}`);
      }
      if (token === EOS_TOKEN_ID) break;
      bytes.push(token);
    }

    const decoder = new TextDecoder("utf-8", { fatal: true });
    for (let length = bytes.length; length >= 0; length -= 1) {
      try {
        return decoder.decode(new Uint8Array(bytes.slice(0, length)));
      } catch {
        // Trim one byte and retry until the remaining prefix is valid UTF-8.
      }
    }
    return "";
  }
}
